// Query TypeMap
declare global {
  interface SanityQueries {
    '*[_type == "dish" && status != "off"] | order(order asc, name asc) {\n    _id, name, detail, price, section, nuts, status\n  }': DISHES_QUERY_RESULT;
    '*[_type == "wine" && status != "off"] | order(order asc, name asc) {\n    _id, name, meta, note, glass, bottle, section, status\n  }': WINES_QUERY_RESULT;
    '*[_type == "pour" && status != "off"] | order(order asc, name asc) {\n    _id, name, detail, price, section, status\n  }': POURS_QUERY_RESULT;
    '*[_id == "story"][0]{\n    text,\n    image {\n      alt,\n      crop,\n      hotspot,\n      asset\n    }\n  }': STORY_QUERY_RESULT;
    '*[_id == "hours"][0]{\n    monday, tuesday, wednesday, thursday, friday, saturday, sunday,\n    specialDates[]{ date, until, closed, opens, closes, note }\n  }': HOURS_QUERY_RESULT;
    '*[_type == "photo" && defined(image.asset)] | order(order asc) {\n    _id,\n    caption,\n    alt,\n    "src": image.asset->url\n  }': PHOTOS_QUERY_RESULT;
  }
}
// Lets @sanity/client releases that predate the global registry read it too
declare module "@sanity/client" {
  interface SanityQueries extends globalThis.SanityQueries {}
}
